import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const root = new ctx.THREE.Group();

  // Store timelines for cleanup
  const timelines = [];

  // Load GLB mesh if provided
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      root.add(gltf.scene);
    });
  }

  // Preserve original Y position for hover animation
  let originalY = undefined;
  function getOriginalY() {
    if (originalY === undefined) originalY = root.position.y;
    return originalY;
  }

  // Hover enter animation (rise-in)
  function onHoverEnter() {
    const targetY = getOriginalY() + 0.15;
    const tl = gsap.timeline();
    tl.to(root.position, { y: targetY, duration: 0.7, ease: 'power3.out' });
    timelines.push(tl);
  }

  // Hover leave animation (return)
  function onHoverLeave() {
    const tl = gsap.timeline();
    tl.to(root.position, { y: getOriginalY(), duration: 0.7, ease: 'power3.out' });
    timelines.push(tl);
  }

  // Click handler (press-down + emit)
  function onClick() {
    const tl = gsap.timeline();
    tl.to(root.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out(1.7)'
    })
      .to(root.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.12,
        ease: 'back.out(1.7)'
      });
    timelines.push(tl);
    ctx.emit('hub-home.select');
  }

  // Attach handlers to userData
  root.userData.handlers = {
    hover: { enter: onHoverEnter, leave: onHoverLeave },
    click: onClick
  };

  // Recursive dispose for cleanup
  function disposeObject(obj) {
    if (obj.geometry) obj.geometry.dispose();
    if (obj.material) {
      if (Array.isArray(obj.material)) {
        obj.material.forEach((m) => m.dispose());
      } else {
        obj.material.dispose();
      }
    }
    obj.children.forEach(disposeObject);
  }

  // Cleanup method
  root.userData.cleanup = function () {
    timelines.forEach((t) => t.kill());
    disposeObject(root);
  };

  return root;
}
